/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 10/01/2023
/// Base Price Version.
/// </summary>
final class METGUPItemBasePriceTableEventHandler
{
}

Method.Source:
    /// <summary>
    /// Inserted hanlder
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">event</param>
    [DataEventHandler(tableStr(GUPItemBasePrice), DataEventType::Inserted)]
    public static void GUPItemBasePrice_onInserted(Common sender, DataEventArgs e)
    {
        GUPItemBasePrice itemBasePrice = sender as GUPItemBasePrice;
                       
        if(GUPParameters::find().METPriceChangeTrackingEnable)
        {
            METPriceChangeEventBasePrice::metProcessTrackChange(itemBasePrice);
        }

        /// CB434, if Base price is Inventory cost and ToDate is not defined then we need to create Standard costing
        if (itemBasePrice.PriceType == GUPBasePriceType::BasePriceInventoryCost && itemBasePrice.ToDate == dateNull())
        {
            itemBasePrice.inventItemPriceCreation();
        }
    }
